CREATE COLUMN TABLE "TEST_AP"."TRS2" ("AbsEntry" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20), "LineID" INTEGER CS_INT NOT NULL , "ParamCode" NVARCHAR(32) NOT NULL , "PrmValAmt" DECIMAL(21,6) CS_FIXED, "PrmValNum" INTEGER CS_INT, "PrmValStr" NVARCHAR(8), "PrmValTxt" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("AbsEntry", "LineID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "TRS2_SECONDARY" ON "TEST_AP"."TRS2" ( "AbsEntry" ASC, "ParamCode" ASC )